import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

sealed class Outcome390 {
    data class Success(val payload: String) : Outcome390()
    data object Failure : Outcome390()
}

fun describe390(outcome: Outcome390): String = when (outcome) {
    is Outcome390.Success -> outcome.payload
    Outcome390.Failure -> "failed"
}
class Counter391 {
    var current: Int by Delegates.observable(34) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
@JvmName("step392")
fun step392(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 41
}
